describe('Lightbox Gallery Modal', () => {
  beforeEach(() => {
    cy.visit('/gallery');
  });

  it('should open lightbox modal when clicking an image in the gallery', () => {
    // Verify gallery is visible
    cy.get('[data-testid="gallery-container"]').should('be.visible');

    // Get the first image in the gallery
    cy.get('[data-testid="gallery-item"]').first().should('be.visible');

    // Click the image to open lightbox
    cy.get('[data-testid="gallery-item"]').first().click();

    // Verify lightbox modal is visible
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    // Verify lightbox has correct content
    cy.get('[data-testid="lightbox-image"]').should('contain', 'gallery-item-1');
    cy.get('[data-testid="lightbox-title"]').should('contain', 'Gallery Image 1');

    // Verify close button is present
    cy.get('[data-testid="lightbox-close-btn"]').should('be.visible');

    // Close the lightbox
    cy.get('[data-testid="lightbox-close-btn"]').click();

    // Verify lightbox is closed
    cy.get('[data-testid="lightbox-modal"]').should('not.exist');
  });

  it('should handle clicking outside lightbox to close it', () => {
    // Open lightbox by clicking an image
    cy.get('[data-testid="gallery-item"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    // Click outside the lightbox to close it
    cy.get('[data-testid="gallery-container"]').click();

    // Verify lightbox is closed
    cy.get('[data-testid="lightbox-modal"]').should('not.exist');

    // Verify gallery is still visible
    cy.get('[data-testid="gallery-container"]').should('be.visible');
  });
});
